// --- THE SAFETY NETS ---

// 1. Catching Synchronous Crashes (e.g., throwing a raw Error)
process.on('uncaughtException', (err) => {
  console.error("[FATAL]: Uncaught Exception detected:", err.message);
  // Always exit gracefully after this!
  // process.exit(1);
});

// 2. Catching Asynchronous Crashes (e.g., failed DB calls without a catch block)
process.on('unhandledRejection', (reason, promise) => {
  console.error("[FATAL]: Unhandled Promise Rejection:", reason);
  // process.exit(1);
});

// Let's trigger one!
setTimeout(() => {
  // We forgot the try/catch block!
  Promise.reject("Database Connection Timeout");
}, 1000);

console.log("Without the safety net, the setTimeout error would violently crash the process.");
